import React, { forwardRef } from 'react';
import classnames from 'clsx';
import {
  TextVariant,
  TextColor,
} from '../../../helpers/constants/design-system';
import { Text } from '../text';
import type { PolymorphicRef } from '../box';
import type { TextProps } from '../text';
import {
  type HelpTextProps,
  type HelpTextComponent,
  HelpTextSeverity,
} from './help-text.types';

/**
 * @deprecated This component is deprecated and will be removed in a future release.
 * Please use the HelpText component from @metamask/design-system-react instead.
 * @see {@link https://github.com/MetaMask/metamask-design-system/blob/main/packages/design-system-react/MIGRATION.md#helptext-component | Migration Guide}
 * @see {@link https://metamask.github.io/metamask-design-system/?path=/docs/react-components-helptext--docs | Storybook Documentation}
 * @see {@link https://github.com/MetaMask/metamask-design-system/tree/main/packages/design-system-react/src/components/HelpText | Component Source}
 */
export const HelpText: HelpTextComponent = forwardRef(
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  <C extends React.ElementType = 'p'>(
    {
      severity,
      color = TextColor.textDefault,
      className,
      children,
      ...props
    }: HelpTextProps<C>,
    ref?: PolymorphicRef<C>,
  ) => {
    const severityColor = () => {
      switch (severity) {
        case HelpTextSeverity.Danger:
          return TextColor.errorDefault;
        case HelpTextSeverity.Warning:
          return TextColor.warningDefault;
        case HelpTextSeverity.Success:
          return TextColor.successDefault;
        case HelpTextSeverity.Info:
          return TextColor.infoDefault;
        // Defaults to HelpTextSeverity.Info
        default:
          return TextColor.textDefault;
      }
    };

    return (
      <Text
        className={classnames('mm-help-text', className ?? '')}
        ref={ref}
        as={children && typeof children === 'object' ? 'div' : 'p'}
        variant={TextVariant.bodySm}
        color={severity ? severityColor() : color}
        {...(props as TextProps<C>)}
      >
        {children}
      </Text>
    );
  },
);
